---@class CatHouseGridCellNode
---@field AttributeIcon2                	Engine.UI.RawImageAlterable
---@field ImgSelect                     	UnityEngine.RectTransform
---@field ImgMaskNormal                     	UnityEngine.RectTransform
---@field lock                          	UnityEngine.RectTransform
---@field TxtName                       	UnityEngine.UI.Text
---@field ImgIcon                       	Engine.UI.RawImageAlterable
---@field ButtonGroup                   	UnityEngine.RectTransform
---@field AnimRoot                   	UnityEngine.RectTransform
local CatHouseGridCellNode = Class('CatHouseGridCellNode')

function CatHouseGridCellNode:__init()
    self.data = nil
    self.cb = nil
    self.position = nil
    self.fileNameId = nil
    self.animator = nil

end

function CatHouseGridCellNode:__delete()
    self.data = nil
    self.cb = nil
    self.position = nil
    self.fileNameId = nil
    self.animator = nil
end

function CatHouseGridCellNode:Awake()
    self.animator = KTool.GetComponent(self.AnimRoot.gameObject, typeof(Animator))
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
    SetButtonAction(self.ButtonGroup.gameObject, Bind(self, self.OnButtonAction))
end

function CatHouseGridCellNode:OnEventCaptureTextureCompleteAction(id, path)
    if self.fileNameId ~= id then return end
    local texture = CatHouseMgr:GetInstance():LoadCaptureTexture(path)
    self.ImgCat.texture = texture
    KTool.SetActive(self.ImgCat.gameObject, true)
end

---@param data CatHouseCatDataVo
---@param position number
---@param isChecked boolean
---@param isUnlocked boolean
---@param cb fun(data:CatHouseCatDataVo, position:number):void
function CatHouseGridCellNode:FreshCommonUI(data, position, isChecked, isUnlocked, cb)
    self.data = data
    self.cb = cb
    self.position = position
    KTool.SetActive(self.ImgSelect.gameObject, checkBool(isChecked))
    KTool.SetActive(self.ImgMaskNormal.gameObject, not checkBool(isChecked))
    KTool.SetActive(self.lock.gameObject, not checkBool(isUnlocked))
    self.TxtName.text = tostring(data.name)
    CfUtils.FillImage(self.AttributeIcon2.gameObject, data.icon)
    CfUtils.FillImage(self.ImgIcon.gameObject, data.icon)
    self.ImgIcon:SetColor(ConstantsCatHouse.ScreenCatDataTypeColor[tostring(data.kind)])
    self.AttributeIcon2:SetColor(ConstantsCatHouse.ScreenCatDataTypeColor[tostring(data.kind)])
    local heritableVo = CatHouseMgr:GetInstance():GetVariationVoByRefId(data.id)
    if heritableVo then
        if isUnlocked then
            ---已解锁的情况下
        end
        --KTool.SetActive(self.ImgCat.gameObject, false)
        --self.fileNameId = CatHouseMgr:GetInstance():CaptureTexture(ConstantsCatHouse.BornType.Adult, table.takeFirst(heritableVo.catId), {data.id})
    end
    if data.skillIdList and #data.skillIdList > 0 then
        --KTool.SetActive(self.ImgIcon.transform.parent.gameObject, true)
        ---@type UnitSkillVo
        local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(table.takeFirst(data.skillIdList))
        self.ImgIcon:LoadSprite(vo.photoPath)
    else
        --KTool.SetActive(self.ImgIcon.transform.parent.gameObject, false)
    end
    if checkBool(isChecked) then
        CfUtils.PlayAnimator(self.AnimRoot.gameObject, "Go")
    else
        CfUtils.PlayAnimator(self.AnimRoot.gameObject, "Default")
    end
end

function CatHouseGridCellNode:PlayAnimGo(index)
    if isNull(self.animator) then
        self.animator = KTool.GetComponent(self.AnimRoot.gameObject, typeof(Animator))
    end
    CfUtils.PlayDelayShowAnimate(self.animator, index)
end

function CatHouseGridCellNode:OnButtonAction()
    if self.cb then
        self.cb(self.data, self.position)
    end
end

function CatHouseGridCellNode:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CatHouseGridCellNode